sealed interface ConnectionState {
    object Disconnected : ConnectionState
    data class Connecting(val initiated: Instant) : ConnectionState
    data class Connected(val sessionId: String) : ConnectionState
}

fun describe(state: ConnectionState): String = when (state) {
    ConnectionState.Disconnected -> "down"
    is ConnectionState.Connecting -> "connecting since ${state.initiated}"
    is ConnectionState.Connected -> state.sessionId   // no else needed
}

